input.script:
services = boundary retry 2 { return list_services() } catch err { return fail("LIST_FAILED", err.code + ": " + err.message) }
overviews = for svc in services {
    res = boundary retry 2 { return search_logs({ service: svc, level: "ERROR", page: 1 }) } catch err {
        return fail("SEARCH_FAILED", svc + ": " + err.code + ": " + err.message)
    }
    return { service: svc, total_items: res.total_items, total_pages: res.total_pages, sample: res.items }
}
return { services, overviews }

